// Monitor: Circuits Verification
bthread("monitor:Circuits", function () {
  while (true) {
    let e = bp.sync({ waitFor: matchAnyCircuitsAdded() });
    let circuit = (e.data.parameters && e.data.parameters["circuit"]) ? e.data.parameters["circuit"] : e.data["circuit"];
    let commit_rate = (e.data.parameters && e.data.parameters["commit_rate"]) ? e.data.parameters["commit_rate"] : e.data["commit_rate"];
    let description = (e.data.parameters && e.data.parameters["description"]) ? e.data.parameters["description"] : e.data["description"];
    let id = (e.data.parameters && e.data.parameters["id"]) ? e.data.parameters["id"] : e.data["id"];
    let install_date = (e.data.parameters && e.data.parameters["install_date"]) ? e.data.parameters["install_date"] : e.data["install_date"];
    let provider = (e.data.parameters && e.data.parameters["provider"]) ? e.data.parameters["provider"] : e.data["provider"];
    let status = (e.data.parameters && e.data.parameters["status"]) ? e.data.parameters["status"] : e.data["status"];
    let tenant = (e.data.parameters && e.data.parameters["tenant"]) ? e.data.parameters["tenant"] : e.data["tenant"];
    let type = (e.data.parameters && e.data.parameters["type"]) ? e.data.parameters["type"] : e.data["type"];
    // Block Deletion while Verifying Existence
    block(matchDeletedCircuits(circuit, commit_rate, description, id, install_date, provider, status, tenant, type), function() {
        verifyCircuitsExists(circuit, commit_rate, description, id, install_date, provider, status, tenant, type);
    });
  }
});

