// Monitor: FrontPorts Verification
bthread("monitor:FrontPorts", function () {
  while (true) {
    let e = bp.sync({ waitFor: matchAnyFrontPortsAdded() });
    let device_id = (e.data.parameters && e.data.parameters["device_id"]) ? e.data.parameters["device_id"] : e.data["device_id"];
    let id = (e.data.parameters && e.data.parameters["id"]) ? e.data.parameters["id"] : e.data["id"];
    let name = (e.data.parameters && e.data.parameters["name"]) ? e.data.parameters["name"] : e.data["name"];
    let type = (e.data.parameters && e.data.parameters["type"]) ? e.data.parameters["type"] : e.data["type"];
    // Block Deletion while Verifying Existence
    block(matchDeletedFrontPorts(device_id, id, name, type), function() {
        verifyFrontPortsExists(device_id, id, name, type);
    });
  }
});

