// Monitor: Notifications Verification
bthread("monitor:Notifications", function () {
  while (true) {
    let e = bp.sync({ waitFor: matchAnyNotificationsAdded() });
    let field1 = (e.data.parameters && e.data.parameters["field1"]) ? e.data.parameters["field1"] : e.data["field1"];
    let field2 = (e.data.parameters && e.data.parameters["field2"]) ? e.data.parameters["field2"] : e.data["field2"];
    let id = (e.data.parameters && e.data.parameters["id"]) ? e.data.parameters["id"] : e.data["id"];
    let limit = (e.data.parameters && e.data.parameters["limit"]) ? e.data.parameters["limit"] : e.data["limit"];
    let offset = (e.data.parameters && e.data.parameters["offset"]) ? e.data.parameters["offset"] : e.data["offset"];
    let ordering = (e.data.parameters && e.data.parameters["ordering"]) ? e.data.parameters["ordering"] : e.data["ordering"];
    // Block Deletion while Verifying Existence
    block(matchDeletedNotifications(field1, field2, id, limit, offset, ordering), function() {
        verifyNotificationsExists(field1, field2, id, limit, offset, ordering);
    });
  }
});

